#!/bin/bash

# ============================================================================
# LIBERO 语言嵌入编码脚本
# 为 LIBERO-goal, LIBERO-object, LIBERO-spatial 数据集生成语言嵌入
# ============================================================================

set -e  # 遇到错误立即退出

# ============================================================================
# 配置参数
# ============================================================================

# GPU 设置
export CUDA_VISIBLE_DEVICES=0

# T5 模型路径
MODEL_PATH="google/t5-v1_1-xxl"

# 配置文件路径
CONFIG_PATH="configs/base.yaml"

# 输出目录
SAVE_DIR="outs/libero_embeddings/"

# Offload 目录（如果 GPU 显存不足 24GB，可以设置此路径）
# OFFLOAD_DIR="/path/to/offload"  # 取消注释并设置路径
OFFLOAD_DIR=""

# ============================================================================
# 环境准备
# ============================================================================

echo "============================================================================"
echo "🚀 LIBERO 语言嵌入编码"
echo "============================================================================"
echo ""

# 获取脚本所在目录
SCRIPT_DIR="$( cd "$( dirname "${BASH_SOURCE[0]}" )" && pwd )"
PROJECT_DIR="$( cd "$SCRIPT_DIR/.." && pwd )"

echo "📂 项目目录: $PROJECT_DIR"
echo "📂 脚本目录: $SCRIPT_DIR"
echo ""

# 切换到项目根目录
cd "$PROJECT_DIR"
echo "✅ 已切换到项目根目录: $(pwd)"
echo ""

# ============================================================================
# 激活 Conda 环境
# ============================================================================

echo "🔧 激活 conda 环境..."
source /share_data/zhukefei/miniconda3/etc/profile.d/conda.sh
conda activate rdt
echo "✅ conda 环境已激活: rdt"
echo "✅ Python 路径: $(which python)"
echo "✅ Python 版本: $(python --version)"
echo ""

# ============================================================================
# 显示配置信息
# ============================================================================

echo "============================================================================"
echo "📋 配置信息"
echo "============================================================================"
echo "GPU:              $CUDA_VISIBLE_DEVICES"
echo "T5 模型:          $MODEL_PATH"
echo "配置文件:         $CONFIG_PATH"
echo "输出目录:         $SAVE_DIR"
if [ -n "$OFFLOAD_DIR" ]; then
    echo "Offload 目录:     $OFFLOAD_DIR"
else
    echo "Offload 目录:     未设置（需要 24GB+ 显存）"
fi
echo ""

# ============================================================================
# 检查依赖
# ============================================================================

echo "🔍 检查依赖..."

# 检查配置文件是否存在
if [ ! -f "$CONFIG_PATH" ]; then
    echo "❌ 错误: 配置文件不存在: $CONFIG_PATH"
        exit 1
    fi
echo "✅ 配置文件: $CONFIG_PATH"
    
    # 检查数据集目录
for dataset in "libero_goal" "libero_object" "libero_spatial"; do
    dataset_dir="data/datasets/$dataset"
    if [ ! -d "$dataset_dir" ]; then
        echo "⚠️  警告: 数据集目录不存在: $dataset_dir"
    else
        file_count=$(find "$dataset_dir" -name "*.hdf5" | wc -l)
        echo "✅ 数据集 $dataset: 找到 $file_count 个 HDF5 文件"
    fi
    done
echo ""

# ============================================================================
# 创建输出目录
# ============================================================================

echo "📁 创建输出目录..."
mkdir -p "$SAVE_DIR"
echo "✅ 输出目录已创建: $SAVE_DIR"
echo ""

# ============================================================================
    # 运行编码脚本
# ============================================================================

echo "============================================================================"
echo "🚀 开始编码语言嵌入"
echo "============================================================================"
echo ""

# 记录开始时间
START_TIME=$(date +%s)

# 运行 Python 脚本
    python scripts/encode_lang_libero.py
    
# 记录结束时间
END_TIME=$(date +%s)
ELAPSED=$((END_TIME - START_TIME))

echo ""
echo "============================================================================"
echo "✅ 编码完成！"
echo "============================================================================"
echo "⏱️  总耗时: ${ELAPSED} 秒 (约 $((ELAPSED / 60)) 分钟)"
echo "📂 输出目录: $SAVE_DIR"
echo ""

# ============================================================================
# 显示结果摘要
# ============================================================================

echo "📊 结果摘要:"
for dataset in "libero_goal" "libero_object" "libero_spatial"; do
    output_dir="$SAVE_DIR/$dataset"
    if [ -d "$output_dir" ]; then
        pt_count=$(find "$output_dir" -name "*.pt" | wc -l)
        echo "  - $dataset: $pt_count 个嵌入文件"
        
        # 显示映射文件位置
        mapping_file="$output_dir/task_instruction_mapping.txt"
        if [ -f "$mapping_file" ]; then
            echo "    映射文件: $mapping_file"
        fi
    else
        echo "  - $dataset: ⚠️ 输出目录不存在"
    fi
done
echo ""

echo "============================================================================"
echo "🎉 全部完成！"
echo "============================================================================"
